var $ = require('jquery')
var env = require('./env')
var util = require('./util')
var viewer = require('./viewer')

/**
  ~~ Backup interaction ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
*/

function noBackupRunning (callback) {
  $.getJSON('backup/status', function (resp) {
    var backupRunning = resp.rc === null
    if (backupRunning) util.log(`▶ Backup in progress`)
    else util.log(`✖ No backup in progress`)
    callback(!backupRunning)
  })
}

function pollBackupStatus (endpoint, ms, callback) {
  noBackupRunning(function (notRunning) {
    if (notRunning) {
      $('.navbar button[type=submit]').toggleClass('btn-success')
      $('.navbar button[type=submit]').toggleClass('btn-warning')
      $('.navbar button[type=submit]').text(`▶ Start Backup`)
      $.getJSON('logs', viewer.updateLogFileList)
      viewer.switchToLog(1)
    } else {
      util.log(`Polling backup status`)
      $.getJSON('backup/status', callback)
      setTimeout(function () {
        pollBackupStatus(endpoint, ms, callback)
      }, ms)
    }
  })
}

function stopBackup () {
  util.log(`Terminating (eventually killing) the backup process`)
  $.post('backup/stop', {}, function (res) {
    util.log(`Message: '${ res.msg }', RC: '${ res.rc }'`)
  })
}

function startBackup (force) {
  if (force) {
    util.log(`Sending backup start request`)
    if (Date.now() - env['lastRun'] >= env['coolDownTime']) {
      env['lastRun'] = Date.now()
      $.post('backup/start', {}, function () {
        $('.navbar button[type=submit]').toggleClass('btn-success')
        $('.navbar button[type=submit]').toggleClass('btn-warning')
        $('.navbar button[type=submit]').text(`✖ Stop Backup`)
        pollBackupStatus('backup/status', env['pollFrequency'],
          function (res) {
            util.log(`Received status update`)
          }
        )
      })
    } else util.log('Restarting backup too fast, ignoring')
  } else {
    if (force === undefined) noBackupRunning(startBackup)
    else stopBackup()
  }
}

module.exports = {
  noBackupRunning: noBackupRunning,
  pollBackupStatus: pollBackupStatus,
  stopBackup: stopBackup,
  startBackup: startBackup
}

"""
backup view
"""

import subprocess
import time

from flask import current_app, render_template, jsonify

from . import blueprint

process = None


@blueprint.route('/backup/start', methods=['POST'])
def backup_start():
    env = dict(current_app.config)
    now = time.time()
    fmt = '%Y-%m-%d-%H:%M:%S'
    env['LOCALTIME'] = time.strftime(fmt, time.localtime(now))
    env['UTC'] = time.strftime(fmt, time.gmtime(now))
    cmd = env['BACKUP_CMD'].format(**env)
    global process
    if process is None or process.returncode is not None:
        # no process ever run or process has terminated
        process = subprocess.Popen(cmd, shell=True, stdin=None, stdout=None, stderr=None)
        msg = "started, pid=%d" % process.pid
    else:
        msg = "already running, pid %d" % process.pid
    return jsonify(dict(msg=msg, pid=process.pid))


@blueprint.route('/backup/stop', methods=['POST'])
def backup_stop():
    global process
    if process is None:
        rc = -1
        msg = 'not running'
    else:
        pid = process.pid
        try:
            process.terminate()
            for t in range(10):
                rc = process.poll()
                if rc is not None:
                    msg = 'terminated pid %d' % pid
                    break
                time.sleep(1)
            else:
                process.kill()
                msg = 'killed pid %d' % pid
                rc = -1
        except ProcessLookupError:
            rc = -1
            msg = 'not running'
    return jsonify(dict(msg=msg, rc=rc))


@blueprint.route('/backup/status')
def backup_rc():
    global process
    if process is not None:
        rc = process.poll()
        if rc is None:
            msg = 'running, pid %d' % process.pid
        else:
            msg = 'not running, last rc=%d' % rc
    else:
        msg = 'not running'
        rc = -1
    return jsonify(dict(msg=msg, rc=rc))

